    correction: [{"quoi":"نترجم","math":"عدد الأصدقاء يقسم 231 و 168، ونريده الأكبر: إنّه ق.م.أ"},{"quoi":"نفكّك إلى عوامل أوّلية","math":"<span dir=\"ltr\" class=\"expr\">231 = 3 × 7 × 11</span> و <span dir=\"ltr\" class=\"expr\">168 = 2<sup>3</sup> × 3 × 7</span>"},{"quoi":"ق.م.أ","math":"العوامل المشتركة بأصغر أسّ: <span dir=\"ltr\" class=\"expr\">3 × 7 = 21</span>"},{"quoi":"نصيب كلّ واحد من الأقلام","math":"<span dir=\"ltr\" class=\"expr\">231 : 21 = 11</span>"},{"quoi":"نصيب كلّ واحد من الكتب","math":"<span dir=\"ltr\" class=\"expr\">168 : 21 = 8</span>"},{"quoi":"عدد الأصدقاء","math":"<span dir=\"ltr\" class=\"expr\">= 21</span>"}],
